                    sessionId: String(session?.id || ''),
                    at: admin.firestore.FieldValue.serverTimestamp(),
                  },
                },
                { merge: true },
              );
            });
          }
        }

        // Plus subscription purchase
        if (kind === 'plus_weekly') {
          if (uid) {
            const until = admin.firestore.Timestamp.fromMillis(Date.now() + PLUS_WEEK_MS);
            await db.doc(`users/${uid}`).set(
              {
                paidPlan: true,
                paidPlanUntil: until,
                updatedAt: admin.firestore.FieldValue.serverTimestamp(),
                billing: {
                  stripeCustomerId: session?.customer || null,
                  stripeSubscriptionId: session?.subscription || null,
                  lastCheckoutSessionId: session?.id || null,
                  lastPaidAt: admin.firestore.FieldValue.serverTimestamp(),
                },
              },
              { merge: true },
            );
          }
        }
      }

      res.json({ received: true });
    } catch (e) {
      logger.error('stripe webhook failed', e);
      // Stripe treats non-2xx as retry; return 500 only for transient errors.
      res.status(500).json({ ok: false, error: 'internal' });
    }
  },
);

