}

function _saGetJobTitleForAi(opts = {}) {
  try {
    const fromOpts =
      opts?.jobTitle ||
      opts?.job_title ||
      opts?.snapshot?.jobTitle ||
      opts?.snapshot?.job_title ||
      opts?.formData?.jobTitle ||
      opts?.formData?.job_title;
    const cleaned = _saCleanJobTitleCandidate(fromOpts);
